const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const bellingham = ee.Geometry.Point([-122.48, 48.75]);
  const startDate = '2021-09-01';
  const endDate = '2021-11-30';

  // 2. Data Acquisition & Check
  // Using CHIRPS daily precipitation data (mm/day)
  let precipCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(bellingham);

  const colSize = precipCol.size().getInfo();
  console.log(`CHIRPS images found: ${colSize}`);

  if (colSize === 0) {
    // Try GPM as fallback
    precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
      .filterDate(startDate, endDate)
      .filterBounds(bellingham)
      .select('precipitation');

    const gpmSize = precipCol.size().getInfo();
    console.log(`GPM fallback images found: ${gpmSize}`);

    if (gpmSize === 0) {
      console.log('No precipitation data available.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Sum all precipitation
  const totalPrecip = precipCol.sum();

  // 4. Calculation
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: bellingham,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const bandName = Object.keys(stats)[0];
  const totalMm = stats[bandName];

  console.log(`Band used: ${bandName}`);
  console.log(`Total precipitation: ${totalMm !== null ? totalMm.toFixed(2) : 'null'} mm`);

  // 5. Validation & Final Answer
  if (totalMm === null || totalMm === undefined || isNaN(totalMm)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (totalMm < 0 || totalMm > 5000) {
    console.log('Result outside valid range.');
    console.log('<answer>C3</answer>');
    return;
  }

  const totalCm = totalMm / 10;
  console.log(`Total precipitation: ${totalCm.toFixed(2)} cm`);
  console.log(`Threshold: 30 cm`);

  if (totalCm >= 30) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
